import{_ as i,l as r,o as e,c as s,v as t,p as n,x as l,d,i as h,S as E}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"掩模刻蚀与侧壁","description":"","frontmatter":{"title":"掩模刻蚀与侧壁","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mask-etch-sidewall.md","filePath":"litho/mask-etch-sidewall.md","lastUpdated":1789023840000}'),p={name:"litho/mask-etch-sidewall.md"};function c(m,a,A,_,D,f){const o=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="掩模刻蚀与侧壁" tabindex="-1">掩模刻蚀与侧壁 <a class="header-anchor" href="#掩模刻蚀与侧壁" aria-label="Permalink to &quot;掩模刻蚀与侧壁&quot;">​</a></h1><div class="epigraph"><p>吸收体边不是数据里的直墙：干法侧壁角改变有效光学边缘，掩模 3D 从这里进入晶圆模型。</p><footer>—— 对照掩模干法刻蚀、侧壁角与 mask 3D 的公开讨论</footer></div><p><a href="/litho/chrome-mosi-films">上一课</a>选定铬或 MoSi（及对照 EUV 吸收体）。缺口是图形如何从胶转到膜：横向偏置、微沟槽、侧壁角。本课钉掩模刻蚀与侧壁。胶的显影与版清洗，留给[下一课](/litho/mask-develop-clean）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/mpc">MPC</a> 用紧凑核去追 AEI CD。本课补核下面的剖面：铬/MoSi/Ta 化合物的反应离子刻蚀是各向异性加聚合物，侧壁常有几度倾角，顶 CD 与底 CD 不同。电磁仿真若当直墙，AIMS 与晶圆会对不齐——尤其 EUV 厚吸收体与斜入射。</p><p>缺口是<strong>三维边</strong>，不是再拟合一次二维偏置。把侧壁写成「美观」，会漏掉它是成像变量。</p><h3 id="微负载与微沟槽" tabindex="-1">微负载与微沟槽 <a class="header-anchor" href="#微负载与微沟槽" aria-label="Permalink to &quot;微负载与微沟槽&quot;">​</a></h3><p>密区与孤立区侧壁角可以不同；铬/石英界面可能出现微沟槽，改变边缘相位。二维 MPC 修顶 CD 时，这些剖面残差留给严格电磁或经验 3D 模型。全芯片 OPC 仍用紧凑近似，但校准要用能看见剖面的计量（截面、AFM、散射）。</p><p><span class="marginnote">过刻石英会做出台阶相移，有时是故意（交替相移），有时是缺陷。本课不把 altPSM 工艺从头讲一遍，只标：侧壁与过刻改变相位边。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工艺：胶做掩、干法刻膜、去胶、量顶/底 CD 与角。EUV 吸收体更厚，深宽比更高，侧壁与脚（footing）对阴影更敏感。MPC 与写剂量不能单独补偿角：角主要由刻蚀化学与过刻时间定。换腔等于换 3D 模型版本。</p><p>与晶圆 <a href="/litho/mask-3d-effect">掩模 3D</a> 衔接：输入剖面来自本课，不是来自设计多边形。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>离子辅助刻蚀在法向快、侧向被聚合物抑制，于是墙有倾角。开口窄时中性基与离子通配变，ARDE 同类效应在掩模纳米尺度出现，密助条根部可能刻不尽或过刻。反射 EUV 里，倾角改变的是吸收体阴影宽度随方位的函数，SMO 光瞳因此与剖面耦合。</p>',14)),(e(),n(E,null,{default:l(()=>[h(o,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20PR%5B%22%E6%8E%A9%E6%A8%A1%E8%83%B6%E5%9B%BE%E5%BD%A2%22%5D%20--%3E%20RIE%5B%22%E5%B9%B2%E6%B3%95%E5%88%BB%E5%90%B8%E6%94%B6%E4%BD%93%22%5D%0A%20%20RIE%20--%3E%20SW%5B%22%E4%BE%A7%E5%A3%81%E8%A7%92%20%2F%20%E9%A1%B6%E5%BA%95%20CD%22%5D%0A%20%20SW%20--%3E%20EMF%5B%22%E6%8E%A9%E6%A8%A1%203D%20%E7%94%B5%E7%A3%81%22%5D%0A%20%20EMF%20--%3E%20WAFER%5B%22%E6%99%B6%E5%9C%86%E7%A9%BA%E4%B8%AD%E5%83%8F%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写某气体配方。不把晶圆 Fin 刻蚀与掩模铬刻蚀写成同一腔。侧壁改善不替代空白片缺陷控制。</p><p>后课默认：吸收体边是带角的三维物体；下一课胶显影与清洗如何在刻蚀前后引入残胶、离子与雾化隐患。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>掩模干法给出倾角边；顶 CD ≠ 光学有效边。</li><li>剖面进入 mask 3D；二维 MPC 只追一层 CD。</li><li>EUV 厚吸收体让侧壁与阴影强耦合。</li><li>出处：掩模 RIE 与 mask 3D 剖面的公开讨论；Mack/Levinson 掩模三维效应论述。</li></ul>',5))])}const k=i(p,[["render",c]]);export{u as __pageData,k as default};
